/*/*/
#include <cstdio>
#include <cstdlib>
#include <vector>
int main(int argc, char **argv) {
    long n = argc > 1 ? strtol(argv[1], 0, 10) : 0;
    std::vector<unsigned> a, b, c;
    a.push_back(1u);
    b.push_back(1u);
    for (long i = 0; i < n; i++) {
        c.clear();
        unsigned carry = 0u;
        size_t m = a.size() > b.size() ? a.size() : b.size();
        for (size_t j = 0; j < m; j++) {
            unsigned s = carry;
            if (j < a.size()) s += a[j];
            if (j < b.size()) s += b[j];
            if (s >= 1000000000u) { s -= 1000000000u; carry = 1u; } else { carry = 0u; }
            c.push_back(s);
        }
        if (carry > 0u) c.push_back(carry);
        a = b;
        b = c;
    }
    printf("%u", a[a.size() - 1]);
    for (size_t j = a.size() - 1; j-- > 0;) printf("%09u", a[j]);
    printf("\n");
    return 0;
}
// */ */
//\
fn main() { //\
    let args: Vec<String> = std::env::args().collect(); //\
    let n: u64 = if args.len() > 1 { args[1].trim().parse().unwrap_or(0) } else { 0 }; //\
    let mut a: Vec<u32> = vec![1]; //\
    let mut b: Vec<u32> = vec![1]; //\
    for _ in 0..n { //\
        let mut c: Vec<u32> = Vec::new(); //\
        let mut carry: u32 = 0; //\
        let m = if a.len() > b.len() { a.len() } else { b.len() }; //\
        for j in 0..m { //\
            let mut s: u32 = carry; //\
            if j < a.len() { s += a[j]; } //\
            if j < b.len() { s += b[j]; } //\
            if s >= 1000000000 { s -= 1000000000; carry = 1; } else { carry = 0; } //\
            c.push(s); //\
        } //\
        if carry > 0 { c.push(carry); } //\
        a = b; //\
        b = c; //\
    } //\
    let mut out = String::new(); //\
    out.push_str(&a[a.len() - 1].to_string()); //\
    for j in (0..a.len() - 1).rev() { //\
        out.push_str(&format!("{:09}", a[j])); //\
    } //\
    println!("{}", out); //\
}
